--- src/Codeunit/CalcMinimumOrderFee.Codeunit.al ---
codeunit 50100 "NVK Calc Minimum Order Fee"
{
    procedure AddFeeIfBelowMinimum(var SalesHeader: Record "Sales Header")
    var
        Setup: Record "NVK Min. Order Fee Setup";
        SalesLine: Record "Sales Line";
        Total: Decimal;
    begin
        Setup.Get();
        if Setup."Fee Item No." = '' then
            exit;
        RemoveFee(SalesHeader);
        SalesLine.SetRange("Document Type", SalesHeader."Document Type");
        SalesLine.SetRange("Document No.", SalesHeader."No.");
        SalesLine.SetRange(Type, SalesLine.Type::Item);
        SalesLine.CalcSums("Line Amount");
        Total := SalesLine."Line Amount";
        if Total >= Setup."Minimum Order Amount" then
            exit;
        InsertFeeLine(SalesHeader, Setup);
    end;

    procedure RemoveFee(var SalesHeader: Record "Sales Header")
    var
        SalesLine: Record "Sales Line";
    begin
        SalesLine.SetRange("Document Type", SalesHeader."Document Type");
        SalesLine.SetRange("Document No.", SalesHeader."No.");
        SalesLine.SetRange("NVK Minimum Order Fee", true);
        SalesLine.DeleteAll(true);
    end;

    local procedure InsertFeeLine(SalesHeader: Record "Sales Header"; Setup: Record "NVK Min. Order Fee Setup")
    var
        SalesLine: Record "Sales Line";
    begin
        SalesLine.Init();
        SalesLine."Document Type" := SalesHeader."Document Type";
        SalesLine."Document No." := SalesHeader."No.";
        SalesLine."Line No." := 990000;
        SalesLine.Validate(Type, SalesLine.Type::Item);
        SalesLine.Validate("No.", Setup."Fee Item No.");
        SalesLine.Validate(Quantity, 1);
        SalesLine.Validate("Unit Price", Setup."Fee Amount");
        SalesLine."NVK Minimum Order Fee" := true;
        SalesLine.Insert(true);
    end;

    [EventSubscriber(ObjectType::Codeunit, Codeunit::"Release Sales Document", 'OnAfterReleaseSalesDoc', '', false, false)]
    local procedure OnAfterReleaseSalesDoc(var SalesHeader: Record "Sales Header")
    begin
        if SalesHeader."Document Type" = SalesHeader."Document Type"::Order then
            AddFeeIfBelowMinimum(SalesHeader);
    end;

    [EventSubscriber(ObjectType::Codeunit, Codeunit::"Release Sales Document", 'OnAfterReopenSalesDoc', '', false, false)]
    local procedure OnAfterReopenSalesDoc(var SalesHeader: Record "Sales Header")
    begin
        RemoveFee(SalesHeader);
    end;
}

