codeunit 50110 "NVK Subscribers"
{
    [EventSubscriber(ObjectType::Table, Database::"Sales Header", 'OnValidateSellToCustomerNoOnBeforeRecallModifyAddressNotification', '', false, false)]
    local procedure SetSalespersonFromUser(var SalesHeader: Record "Sales Header")
    var
        UserSetup: Record "User Setup";
    begin
        // Nordvik vill att inloggad användare alltid blir säljare på ordern, inte kundens standardsäljare
        if UserSetup.Get(UserId) and (UserSetup."Salespers./Purch. Code" <> '') then
            SalesHeader.Validate("Salesperson Code", UserSetup."Salespers./Purch. Code");
    end;

    [EventSubscriber(ObjectType::Table, Database::"Production Order", 'OnAfterInitRecord', '', false, false)]
    local procedure SetLocationOnProdOrder(var ProductionOrder: Record "Production Order")
    begin
        if ProductionOrder."Location Code" = '' then
            ProductionOrder."Location Code" := 'PROD';
    end;

    [EventSubscriber(ObjectType::Codeunit, Codeunit::"Copy Document Mgt.", 'OnBeforeUpdateCustLedgEntry', '', false, false)]
    local procedure SkipCrMemoApplication(var ToSalesHeader: Record "Sales Header"; var IsHandled: Boolean)
    begin
        // Kreditnotor ska inte kopplas automatiskt mot fakturan vid kopiering
        IsHandled := true;
    end;
}

