--- src/Codeunit/PurchOrderXML.Codeunit.al ---
codeunit 50130 "NVK Purch. Order XML"
{
    procedure ExportOrder(PurchHeader: Record "Purchase Header")
    var
        PurchLine: Record "Purchase Line";
        TempBlob: Codeunit "Temp Blob";
        Xml: XmlDocument;
        Root: XmlElement;
        OutStr: OutStream;
        InStr: InStream;
        FileName: Text;
    begin
        PurchHeader.TestField("Buy-from Vendor No.");
        Xml := XmlDocument.Create();
        Root := XmlElement.Create('PurchaseOrder');
        Root.Add(XmlElement.Create('OrderNo', '', PurchHeader."No."));
        Root.Add(XmlElement.Create('VendorNo', '', PurchHeader."Buy-from Vendor No."));
        Root.Add(XmlElement.Create('OrderDate', '', Format(PurchHeader."Order Date", 0, 9)));
        PurchLine.SetRange("Document Type", PurchHeader."Document Type");
        PurchLine.SetRange("Document No.", PurchHeader."No.");
        PurchLine.SetRange(Type, PurchLine.Type::Item);
        if PurchLine.FindSet() then
            repeat
                AddLine(Root, PurchLine);
            until PurchLine.Next() = 0;
        Xml.Add(Root);
        TempBlob.CreateOutStream(OutStr, TextEncoding::UTF8);
        Xml.WriteTo(OutStr);
        TempBlob.CreateInStream(InStr);
        FileName := StrSubstNo('PO_%1.xml', PurchHeader."No.");
        DownloadFromStream(InStr, '', '', '', FileName);
    end;

    local procedure AddLine(var Root: XmlElement; PurchLine: Record "Purchase Line")
    var
        Line: XmlElement;
    begin
        Line := XmlElement.Create('Line');
        Line.Add(XmlElement.Create('ItemNo', '', PurchLine."Vendor Item No."));
        Line.Add(XmlElement.Create('Quantity', '', Format(PurchLine.Quantity, 0, 9)));
        Line.Add(XmlElement.Create('UnitCost', '', Format(PurchLine."Direct Unit Cost", 0, 9)));
        Root.Add(Line);
    end;
}

