        field(description; Rec.Description) { }
        field(baseUnitOfMeasure; Rec."Base Unit of Measure") { }
        field(pimId; Rec."NVK PIM Id") { }
        field(blocked; Rec.Blocked) { }
    } } }
    trigger OnInsertRecord(BelowxRec: Boolean): Boolean
    var
        Setup: Record "NVK PIM Setup";
    begin
        if Setup.Get() then begin
            if Rec."Item Category Code" = '' then
                Rec.Validate("Item Category Code", Setup."Default Item Category");
            if Setup."Block New Items" then
                Rec.Blocked := true;
        end;
        Rec."NVK Last PIM Sync" := CurrentDateTime();
    end;
}

