--- src/Codeunit/CustomCreditLimitMgt.Codeunit.al ---
codeunit 50101 "NVK Custom Credit Limit Mgt."
{
    procedure CheckCreditLimit(SalesHeader: Record "Sales Header")
    var
        Customer: Record Customer;
        Balance: Decimal;
    begin
        Customer.Get(SalesHeader."Bill-to Customer No.");
        if Customer."NVK Custom Credit Limit" = 0 then
            exit;
        Customer.CalcFields("Balance (LCY)");
        SalesHeader.CalcFields("Amount Including VAT");
        Balance := Customer."Balance (LCY)" + SalesHeader."Amount Including VAT";
        if Balance > Customer."NVK Custom Credit Limit" then
            Error('Kundens saldo %1 överstiger den egna kreditlimiten %2. Ordern kan inte frisläppas.', Balance, Customer."NVK Custom Credit Limit");
    end;

    [EventSubscriber(ObjectType::Codeunit, Codeunit::"Release Sales Document", 'OnBeforeReleaseSalesDoc', '', false, false)]
    local procedure OnBeforeReleaseSalesDoc(var SalesHeader: Record "Sales Header")
    begin
        if SalesHeader."Document Type" = SalesHeader."Document Type"::Order then
            CheckCreditLimit(SalesHeader);
    end;
}

